/**
 * LifeTree i18n message catalog.
 *
 * Supported locales:
 *  - zh-CN  简体中文 (default)
 *  - zh-TW  繁體中文
 *  - en     English
 *  - es     Español
 *  - de     Deutsch
 *  - fr     Français
 *
 * Missing keys fall back to zh-CN, then to the key itself.
 */

export const LOCALES = ["zh-CN", "zh-TW", "en", "es", "de", "fr"] as const;
export type Locale = (typeof LOCALES)[number];

export const DEFAULT_LOCALE: Locale = "zh-CN";

export const LOCALE_LABELS: Record<Locale, string> = {
  "zh-CN": "简体中文",
  "zh-TW": "繁體中文",
  en: "English",
  es: "Español",
  de: "Deutsch",
  fr: "Français",
};

export const LOCALE_NAMES: Record<Locale, string> = {
  "zh-CN": "简中",
  "zh-TW": "繁中",
  en: "EN",
  es: "ES",
  de: "DE",
  fr: "FR",
};

